import { basename } from "node:path";
import { defineTool } from "../../definition.js";
import { jsonResponse, jsonError, isZodError, zodError } from "../../../util/json_response.js";
import { decodeBase64, readAllowedLocalFile } from "../../../util/safe_local_file.js";
import { installThemeSchema, LIMITS } from "./schemas.js";
import { detailedTheme, unwrapTheme } from "./projections.js";
import { requireThemeWrite, themeMutation, themeMutationError, validateRepositoryUrl, writeAnnotations } from "./common.js";

function archiveMime(filename: string): string | null {
  const lower = filename.toLowerCase();
  if (lower.endsWith(".zip")) return "application/zip";
  if (lower.endsWith(".tar.gz") || lower.endsWith(".tgz") || lower.endsWith(".gz")) return "application/gzip";
  return null;
}

export const installThemeTool = defineTool({
  name: "discourse_install_theme",
  title: "Install Theme",
  description: "Install a Git repository or ZIP/gzip archive. Set source to exactly one nested variant: {kind:repository, remote_url...}, {kind:archive, archive_data...}, or {kind:archive, archive_path...}; never add placeholder fields from another variant. External code and migrations can have site-wide impact and are not sandboxed.",
  schema: installThemeSchema,
  availability: "writes_enabled",
  toolsets: ["themes"],
  annotations: writeAnnotations(true, false),
  handler: async (input, _extra, ctx, opts) => {
    let attempted = false;
    try {
      const args = installThemeSchema.parse(input);
      const accessError = requireThemeWrite(ctx.siteState, opts);
      if (accessError) return accessError;
      const source = args.source;
      if (source.kind === "repository" && source.force_placeholder && args.confirm_force_placeholder !== true) return jsonError("confirm_force_placeholder=true is required when force_placeholder is requested");
      if (source.kind === "archive" && source.replace_theme_id && args.confirm_replace !== true) return jsonError("confirm_replace=true is required when replacing a theme");
      if (source.kind === "archive" && source.run_migrations && args.confirm_run_migrations !== true) return jsonError("confirm_run_migrations=true is required when archive migrations will run");
      const { base, client } = ctx.siteState.ensureSelectedSite();
      let response: unknown;
      if (source.kind === "repository") {
        const remote = source.remote_url;
        const urlError = validateRepositoryUrl(remote);
        if (urlError) return jsonError(urlError, { code: "invalid_parameters" });
        const payload: Record<string, unknown> = { remote: remote.trim() };
        if (source.branch !== undefined) payload.branch = source.branch;
        if (source.force_placeholder) payload.force = true;
        attempted = true;
        response = await themeMutation(base, () => client.postNoRetry("/admin/themes/import.json", payload));
      } else {
        let data: Buffer;
        let filename: string;
        if ("archive_data" in source) {
          filename = basename(source.archive_data.filename);
          data = decodeBase64(source.archive_data.base64, LIMITS.archive);
        } else {
          const file = await readAllowedLocalFile(source.archive_path, ctx.allowedUploadPaths, LIMITS.archive);
          filename = basename(file.path);
          data = file.data;
        }
        const mime = archiveMime(filename);
        if (!mime) return jsonError("Theme archives must use a supported .zip, .gz, .tgz, or .tar.gz filename");
        const form = new FormData();
        form.set("theme", new Blob([new Uint8Array(data)], { type: mime }), filename);
        if (source.replace_theme_id !== undefined) form.set("theme_id", String(source.replace_theme_id));
        form.set("components", source.component_update_mode === "add_missing" ? "add" : source.component_update_mode);
        if (!source.run_migrations) form.set("skip_migrations", "true");
        attempted = true;
        response = await themeMutation(base, () => client.postMultipart("/admin/themes/import.json", form, { expectedStatus: 201 }));
      }
      const raw = unwrapTheme(response);
      const remote = raw.remote_theme as Record<string, unknown> | undefined;
      const placeholderEvidence = source.kind === "repository" && source.force_placeholder
        ? (remote?.last_error_text ? true : null)
        : false;
      return jsonResponse({
        source: source.kind,
        created_or_replaced: true,
        force_fallback_requested: source.kind === "repository" && source.force_placeholder,
        placeholder_created: placeholderEvidence,
        remote_attached: raw.remote_theme_id !== undefined ? raw.remote_theme_id !== null : null,
        theme: detailedTheme(response, false),
        code_safety_validated: false,
      });
    } catch (error) {
      if (isZodError(error)) return zodError(error);
      return themeMutationError("Failed to install theme", error, attempted);
    }
  },
});

import { z } from "zod";
import { defineTool } from "../../definition.js";
import { requireWriteAccess } from "../../../util/access.js";
import { jsonError, jsonResponse, withRateLimit, zodError } from "../../../util/json_response.js";
import {
  allowedActionFieldNames,
  availableActions,
  moderationError,
  normalizeReviewContext,
} from "./common.js";

const schema = z.object({
  reviewable_id: z.number().int().positive().describe("Reviewable ID from list/detail"),
  action_id: z.string().trim().min(1).describe("Exact available_actions[].id from the current reviewable; the MCP maps its server_action to the route"),
  expected_version: z.number().int().min(0).optional().describe("Version observed during review; fail closed if it has changed"),
  additional_fields: z.record(z.unknown()).optional().describe("Only fields advertised by the selected dynamic action contract"),
  confirm: z.literal(true).describe("Explicit acknowledgement that the selected action may delete content, delete users, or block accounts"),
}).strict();

export const performReviewableActionTool = defineTool({
  name: "discourse_perform_reviewable_action",
  title: "Perform Reviewable Action",
  description: "Perform one exact dynamic action after a fresh serialized preflight. Choose by the action's full description, not label alone (for example delete-and-agree differs from delete-and-ignore). The displayed action ID may be UI-prefixed; this tool safely routes its server_action. Requires confirm=true and write enablement.",
  schema,
  availability: "writes_enabled",
  toolsets: ["moderation"],
  annotations: { destructiveHint: true, readOnlyHint: false, idempotentHint: false, openWorldHint: true },
  handler: async (input, _extra, ctx, opts) => {
    const parsed = schema.safeParse(input);
    if (!parsed.success) return zodError(parsed.error);
    const accessError = requireWriteAccess(ctx.siteState, opts.allowWrites);
    if (accessError) return accessError;

    const { reviewable_id, action_id, expected_version, additional_fields = {} } = parsed.data;
    const { base, client } = ctx.siteState.ensureSelectedSite();
    return withRateLimit(`discourse-api:${base}`, async () => {
      let mutationAttempted = false;
      let performedAction: string | undefined;
      try {
        const fresh = await client.get(`/review/${reviewable_id}.json`) as any;
        const reviewable = fresh?.reviewable ?? (Array.isArray(fresh?.reviewables) ? fresh.reviewables[0] : fresh);
        const action = availableActions(reviewable, fresh).find((candidate) =>
          String(candidate.id) === action_id || String(candidate.server_action) === action_id,
        );
        if (!action) {
          return jsonError("Reviewable action is not currently available; refresh detail and use one exact available action ID", {
            reviewable_id,
            action_id,
          });
        }

        performedAction = typeof action.server_action === "string" && action.server_action
          ? action.server_action
          : String(action.id);
        const currentVersion = reviewable?.version;
        if (typeof currentVersion !== "number") {
          return jsonError("Fresh reviewable response did not include a usable version; action was not performed", { reviewable_id });
        }
        if (expected_version !== undefined && expected_version !== currentVersion) {
          return jsonError("Reviewable version changed; action was not performed", {
            reviewable_id,
            expected_version,
            current_version: currentVersion,
          });
        }

        const allowed = allowedActionFieldNames(action);
        if (action.require_reject_reason === true) allowed.add("reject_reason");
        const supplied = Object.keys(additional_fields);
        const disallowed = supplied.filter((name) => !allowed.has(name));
        if (disallowed.length > 0) {
          return jsonError("Additional fields are not allowed by the selected action contract", {
            reviewable_id,
            action_id,
            disallowed_fields: disallowed,
            allowed_fields: [...allowed],
          });
        }

        mutationAttempted = true;
        const result = await client.put(
          `/review/${reviewable_id}/perform/${encodeURIComponent(performedAction!)}.json`,
          { version: currentVersion, ...additional_fields },
        ) as any;
        const performResult = result?.reviewable_perform_result ?? result;
        return jsonResponse({
          success: performResult?.success ?? true,
          reviewable_id,
          requested_action_id: action_id,
          performed_action: performedAction,
          removed_reviewable_ids: performResult?.remove_reviewable_ids ?? [],
          version: performResult?.version ?? null,
          remaining_reviewable_count: performResult?.reviewable_count ?? null,
          unseen_reviewable_count: performResult?.unseen_reviewable_count ?? null,
          reviewable: result?.reviewable ? normalizeReviewContext(result).reviewable : null,
          upstream_result: performResult,
        });
      } catch (error) {
        return moderationError("perform reviewable action", error, {
          reviewable_id,
          action_id,
          performed_action: performedAction,
          mutation_attempted: mutationAttempted,
        });
      }
    }, 1000);
  },
});

import { z } from "zod";
import { defineTool } from "../../definition.js";
import { jsonResponse, withRateLimit } from "../../../util/json_response.js";
import { bounded, queryString, readAnnotations, upstreamError } from "../common/helpers.js";

export const USER_ACTION_TYPES = {
  likes: 1,
  was_liked: 2,
  topics: 4,
  replies: 5,
  responses: 6,
  mentions: 7,
  quotes: 9,
  edits: 11,
  private_messages_sent: 12,
  private_messages_received: 13,
  solved: 15,
  assigned: 16,
  linked: 17,
} as const;
export type UserActionName = keyof typeof USER_ACTION_TYPES;
const actionNamesById = new Map<number, string>(Object.entries(USER_ACTION_TYPES).map(([name, id]) => [id, name]));
const actionName = z.enum(Object.keys(USER_ACTION_TYPES) as [UserActionName, ...UserActionName[]]);

const schema = z.object({
  username: z.string().min(1),
  acting_username: z.string().min(1).optional(),
  action_types: z.array(actionName).min(1).optional(),
  offset: z.number().int().min(0).optional(),
  limit: z.number().int().min(1).max(100).optional(),
});

export function projectUserAction(action: any, maxReadLength: number) {
  return {
    action_type: actionNamesById.get(action?.action_type) ?? "unknown",
    action_type_id: action?.action_type ?? null,
    id: action?.id ?? null,
    post_id: action?.post_id ?? action?.id ?? null,
    topic_id: action?.topic_id ?? null,
    post_number: action?.post_number ?? null,
    username: action?.username ?? null,
    acting_username: action?.acting_username ?? null,
    target_username: action?.target_username ?? null,
    slug: action?.slug ?? null,
    title: action?.title ?? null,
    category_id: action?.category_id ?? null,
    created_at: action?.created_at ?? null,
    excerpt: bounded(action?.excerpt, maxReadLength),
  };
}

export function projectLegacyUserPost(action: any) {
  return {
    id: action?.post_id ?? action?.id ?? null,
    topic_id: action?.topic_id,
    post_number: action?.post_number,
    slug: action?.slug,
    title: action?.title,
    created_at: action?.created_at,
    excerpt: action?.excerpt || null,
    category_id: action?.category_id || null,
  };
}

export const listUserActionsTool = defineTool({
  name: "discourse_list_user_actions",
  title: "List User Actions",
  description: "List a user's visible activity using model-friendly action names. Plugin-backed action families can legitimately be empty; emptiness does not prove that a feature is unavailable.",
  schema,
  availability: "always",
  toolsets: ["activity"],
  annotations: readAnnotations(),
  handler: async ({ username, acting_username, action_types, offset = 0, limit = 30 }, _extra, ctx) => {
    try {
      const { base, client } = ctx.siteState.ensureSelectedSite();
      const filter = action_types?.map((name) => USER_ACTION_TYPES[name]).join(",");
      const upstreamLimit = limit < 100 ? limit + 1 : limit;
      const path = `/user_actions.json${queryString({ username, acting_username, offset, limit: upstreamLimit, filter })}`;
      const data = await withRateLimit(`discourse-api:${base}`, () => client.get(path), 200) as any;
      const upstream = Array.isArray(data?.user_actions) ? data.user_actions : [];
      const rows = upstream.slice(0, limit).map((action: any) => projectUserAction(action, ctx.maxReadLength));
      const hasMore = limit < 100 ? upstream.length > limit : undefined;
      return jsonResponse({ actions: rows, categories: Array.isArray(data?.categories) ? data.categories : [], meta: { offset, limit, returned: rows.length, has_more: hasMore ?? null, next_offset: hasMore ? offset + rows.length : null } });
    } catch (error) {
      return upstreamError(`Failed to list actions for ${username}`, error);
    }
  },
});

#!/usr/bin/env node
import { constants, generateKeyPairSync, privateDecrypt, randomBytes } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { createInterface } from "node:readline";

interface KeyPair {
  publicKey: string;
  privateKey: string;
}

export interface GenerateOptions {
  site: string;
  scopes?: string;
  applicationName?: string;
  clientId?: string;
  nonce?: string;
  payload?: string;
  saveTo?: string;
}

export interface DeviceAuthorization {
  deviceCode: string;
  userCode: string;
  verificationUri: string;
  verificationUriWithRequest?: string;
  expiresIn: number;
  interval: number;
}

interface DecryptedPayload {
  key: string;
  nonce: string;
  push?: boolean;
  api?: number;
  expires_at?: string;
}

type Fetch = typeof fetch;
type Sleep = (milliseconds: number) => Promise<void>;

const DEFAULT_APPLICATION_NAME = "Discourse MCP";
const DEFAULT_CLIENT_ID = "discourse-mcp";
const DEFAULT_SCOPES = "read,write";
const DEVICE_AUTH_HEADER = "Auth-Api-Device-Code";

function siteUrl(site: string, path: string): URL {
  return new URL(`${site.replace(/\/+$/, "")}${path}`);
}

function generateKeyPair(): KeyPair {
  const { publicKey, privateKey } = generateKeyPairSync("rsa", {
    modulusLength: 2048,
    publicKeyEncoding: {
      type: "spki",
      format: "pem",
    },
    privateKeyEncoding: {
      type: "pkcs8",
      format: "pem",
    },
  });

  return { publicKey, privateKey };
}

export function buildAuthorizationUrl(
  options: GenerateOptions,
  publicKey: string,
  nonce: string
): string {
  const url = siteUrl(options.site, "/user-api-key/new");
  url.search = new URLSearchParams({
    application_name: options.applicationName || DEFAULT_APPLICATION_NAME,
    client_id: options.clientId || DEFAULT_CLIENT_ID,
    scopes: options.scopes || DEFAULT_SCOPES,
    public_key: publicKey,
    nonce,
  }).toString();
  return url.toString();
}

export function decryptPayload(
  encryptedPayload: string,
  privateKey: string,
  padding: "pkcs1" | "oaep"
): DecryptedPayload {
  try {
    const buffer = Buffer.from(encryptedPayload, "base64");
    const decrypted = privateDecrypt(
      {
        key: privateKey,
        padding:
          padding === "oaep" ? constants.RSA_PKCS1_OAEP_PADDING : constants.RSA_PKCS1_PADDING,
      },
      buffer
    );
    const result = JSON.parse(decrypted.toString("utf8")) as Partial<DecryptedPayload>;
    if (typeof result.key !== "string" || !result.key) {
      throw new Error("missing 'key' field");
    }
    if (typeof result.nonce !== "string") {
      throw new Error("missing 'nonce' field");
    }
    return result as DecryptedPayload;
  } catch (error: any) {
    throw new Error(`Failed to decrypt payload: ${error?.message || String(error)}`);
  }
}

async function responseError(response: Response): Promise<Error> {
  const body = await response.text().catch(() => "");
  const detail = body ? `: ${body}` : "";
  return new Error(`Request failed with HTTP ${response.status}${detail}`);
}

export async function supportsDeviceAuthorization(
  site: string,
  fetchImpl: Fetch = fetch
): Promise<boolean> {
  const response = await fetchImpl(siteUrl(site, "/user-api-key/new"), { method: "HEAD" });
  if (response.status === 404 || response.status === 405) return false;
  if (!response.ok) throw await responseError(response);
  return response.headers.get(DEVICE_AUTH_HEADER)?.toLowerCase() === "true";
}

export async function createDeviceAuthorization(
  options: GenerateOptions,
  publicKey: string,
  nonce: string,
  fetchImpl: Fetch = fetch
): Promise<DeviceAuthorization> {
  const response = await fetchImpl(siteUrl(options.site, "/user-api-key/device.json"), {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      application_name: options.applicationName || DEFAULT_APPLICATION_NAME,
      client_id: options.clientId || DEFAULT_CLIENT_ID,
      scopes: options.scopes || DEFAULT_SCOPES,
      public_key: publicKey,
      nonce,
      padding: "oaep",
    }),
  });
  if (!response.ok) throw await responseError(response);

  const body = (await response.json()) as Record<string, unknown>;
  const validVerificationUri =
    typeof body.verification_uri === "string" && URL.canParse(body.verification_uri);
  const validRequestUri =
    body.verification_uri_with_request === undefined ||
    (typeof body.verification_uri_with_request === "string" &&
      URL.canParse(body.verification_uri_with_request));
  if (
    typeof body.device_code !== "string" ||
    !/^[a-f\d]{64}$/i.test(body.device_code) ||
    typeof body.user_code !== "string" ||
    !/^[A-Z2-9]{4}-[A-Z2-9]{4}$/.test(body.user_code) ||
    !validVerificationUri ||
    !validRequestUri ||
    typeof body.expires_in !== "number" ||
    !Number.isFinite(body.expires_in) ||
    body.expires_in <= 0 ||
    typeof body.interval !== "number" ||
    !Number.isFinite(body.interval) ||
    body.interval <= 0
  ) {
    throw new Error("Invalid device authorization response");
  }

  return {
    deviceCode: body.device_code,
    userCode: body.user_code,
    verificationUri: body.verification_uri as string,
    verificationUriWithRequest:
      typeof body.verification_uri_with_request === "string"
        ? body.verification_uri_with_request
        : undefined,
    expiresIn: body.expires_in,
    interval: body.interval,
  };
}

export async function pollDeviceAuthorization(
  site: string,
  authorization: DeviceAuthorization,
  fetchImpl: Fetch = fetch,
  sleep: Sleep = (milliseconds) => new Promise((resolve) => setTimeout(resolve, milliseconds))
): Promise<string> {
  const deadline = Date.now() + authorization.expiresIn * 1000;
  const interval = Math.max(1, authorization.interval) * 1000;

  while (Date.now() < deadline) {
    const response = await fetchImpl(siteUrl(site, "/user-api-key/device/poll.json"), {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ device_code: authorization.deviceCode }),
    });
    if (!response.ok) throw await responseError(response);

    const body = (await response.json()) as Record<string, unknown>;
    switch (body.status) {
      case "authorization_pending":
        await sleep(interval);
        break;
      case "authorized":
        if (typeof body.payload !== "string" || !body.payload) {
          throw new Error("Invalid authorized response: missing payload");
        }
        return body.payload;
      case "access_denied":
        throw new Error("The authorization request was denied");
      case "expired_token":
        throw new Error("The authorization request expired");
      default:
        throw new Error(`Unexpected device authorization status: ${String(body.status)}`);
    }
  }

  throw new Error("Timed out waiting for authorization");
}

async function promptForInput(question: string): Promise<string> {
  const rl = createInterface({ input: process.stdin, output: process.stdout });
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

async function saveToProfile(
  profilePath: string,
  site: string,
  userApiKey: string,
  clientId: string
): Promise<void> {
  let profile: any = {};

  try {
    const content = await readFile(profilePath, "utf8");
    profile = JSON.parse(content);
  } catch {
    // File doesn't exist or is invalid, start fresh
  }

  if (!profile.auth_pairs) {
    profile.auth_pairs = [];
  }

  // Remove any existing entry for this site
  profile.auth_pairs = profile.auth_pairs.filter((pair: any) => pair.site !== site);

  // Add new entry
  profile.auth_pairs.push({
    site,
    user_api_key: userApiKey,
    user_api_client_id: clientId,
  });

  await writeFile(profilePath, JSON.stringify(profile, null, 2), "utf8");
}

async function getLegacyPayload(
  options: GenerateOptions,
  publicKey: string,
  nonce: string
): Promise<string> {
  const authUrl = buildAuthorizationUrl(options, publicKey, nonce);
  console.error("This Discourse site does not support device authorization.");
  console.error("Please visit this URL to authorize the application:\n");
  console.error(authUrl);
  console.error("");

  if (options.payload) return options.payload;

  console.error("After authorizing, copy the encrypted payload displayed by Discourse.\n");
  const payload = await promptForInput("Paste the encrypted payload here: ");
  if (!payload) throw new Error("No payload provided");
  return payload;
}

export async function generateUserApiKey(options: GenerateOptions): Promise<void> {
  if (!options.site) {
    console.error(`
Usage: discourse-mcp generate-user-api-key [options]

Options:
  --site <url>              Discourse site URL (required)
  --scopes <scopes>         Comma-separated scopes (default: read,write)
  --application-name <name> Application name (default: Discourse MCP)
  --client-id <id>          Client ID (default: discourse-mcp)
  --nonce <nonce>           Nonce for request (default: random)
  --payload <payload>       Use a legacy encrypted payload directly
  --save-to <file>          Save to profile file instead of printing
  --help, -h                Show this help message

Examples:
  discourse-mcp generate-user-api-key --site https://discourse.example.com
  discourse-mcp generate-user-api-key --site https://discourse.example.com --save-to profile.json
`);
    process.exit(1);
  }

  console.error("\n🔑 Discourse User API Key Generator\n");
  console.error(`Site: ${options.site}`);
  console.error(`Scopes: ${options.scopes || DEFAULT_SCOPES}\n`);
  console.error("Generating RSA key pair...");
  const { publicKey, privateKey } = generateKeyPair();
  const nonce = options.nonce || randomBytes(32).toString("hex");
  console.error("✓ Key pair generated\n");

  let encryptedPayload: string;
  let padding: "pkcs1" | "oaep";

  if (!options.payload && (await supportsDeviceAuthorization(options.site))) {
    console.error("Requesting device authorization...");
    const authorization = await createDeviceAuthorization(options, publicKey, nonce);
    const verificationUri =
      authorization.verificationUriWithRequest || authorization.verificationUri;
    console.error("\nOpen this URL in your browser:\n");
    console.error(verificationUri);
    console.error(`\nEnter this code when prompted: ${authorization.userCode}`);
    console.error("\nWaiting for authorization...");
    encryptedPayload = await pollDeviceAuthorization(options.site, authorization);
    padding = "oaep";
  } else {
    encryptedPayload = await getLegacyPayload(options, publicKey, nonce);
    padding = "pkcs1";
  }

  console.error("\nDecrypting payload...");
  const result = decryptPayload(encryptedPayload, privateKey, padding);
  if (result.nonce !== nonce) {
    throw new Error("Invalid response: nonce did not match the authorization request");
  }
  console.error("✓ User API Key retrieved successfully\n");

  const clientId = options.clientId || DEFAULT_CLIENT_ID;
  if (options.saveTo) {
    await saveToProfile(options.saveTo, options.site, result.key, clientId);
    console.error(`✓ Saved to profile: ${options.saveTo}\n`);
    console.log(JSON.stringify({ success: true, profile: options.saveTo }, null, 2));
  } else {
    console.error("Add this to your auth_pairs configuration:\n");
    console.log(
      JSON.stringify(
        {
          site: options.site,
          user_api_key: result.key,
          user_api_client_id: clientId,
        },
        null,
        2
      )
    );
    console.error("\nOr use --save-to <profile.json> to save automatically.");
  }
}

async function main() {
  const args = process.argv.slice(2);
  const options: GenerateOptions = { site: "" };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    const next = args[i + 1];

    switch (arg) {
      case "--site":
        options.site = next;
        i++;
        break;
      case "--scopes":
        options.scopes = next;
        i++;
        break;
      case "--application-name":
        options.applicationName = next;
        i++;
        break;
      case "--client-id":
        options.clientId = next;
        i++;
        break;
      case "--nonce":
        options.nonce = next;
        i++;
        break;
      case "--payload":
        options.payload = next;
        i++;
        break;
      case "--save-to":
        options.saveTo = next;
        i++;
        break;
    }
  }

  try {
    await generateUserApiKey(options);
  } catch (error: any) {
    console.error(`\n❌ Error: ${error?.message || String(error)}`);
    process.exit(1);
  }
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(`Fatal error: ${error}`);
    process.exit(1);
  });
}

