  }
});

import test from "node:test";
import assert from "node:assert/strict";
import { Logger } from "../util/logger.js";
import { SiteState } from "../site/state.js";
import { builtinTools } from "../tools/builtin/catalog.js";
import type { AuthMode } from "../http/client.js";
import type { ToolContext, ToolRegistrationOptions } from "../tools/types.js";

function setup(auth: AuthMode, allowWrites = true) {
  const logger = new Logger("silent");
  const siteState = new SiteState({ logger, timeoutMs: 5_000, defaultAuth: auth });
  siteState.selectSite("https://example.com");
  const ctx = { server: {} as any, siteState, logger, maxReadLength: 1_000 } satisfies ToolContext;
  const opts = { allowWrites, toolsMode: "discourse_api_only" } satisfies ToolRegistrationOptions;
  return { ctx, opts };
}

function body(result: any) { return JSON.parse(result.content[0].text); }
async function invoke(name: string, input: Record<string, unknown>, ctx: ToolContext, opts: ToolRegistrationOptions) {
  const tool = builtinTools.find((candidate) => candidate.name === name);
  assert.ok(tool, `missing ${name}`);
  return tool.handler(input as any, {} as any, ctx, opts);
}

function mockFetch(responder: (request: Request, index: number) => Response) {
  const original = globalThis.fetch;
  const requests: Request[] = [];
  globalThis.fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
    const request = new Request(input, init);
    requests.push(request);
    return responder(request, requests.length - 1);
  }) as any;
  return { requests, restore: () => { globalThis.fetch = original; } };
}

test("acting-user writes reject User API Keys before HTTP", async () => {
  const { ctx, opts } = setup({ type: "user_api_key", key: "user-key" });
  const mock = mockFetch(() => Response.json({}));
  try {
    const result = await invoke("discourse_create_post", { topic_id: 1, raw: "body", author_username: "alice" }, ctx, opts);
    assert.equal(result.isError, true);
    assert.match(body(result).error, /global Discourse API key/);
    assert.equal(mock.requests.length, 0);
  } finally { mock.restore(); }
});

test("created posts report actual and requested attribution", async () => {
  const { ctx, opts } = setup({ type: "api_key", key: "global", username: "admin" });
  const mock = mockFetch((request) => {
    assert.equal(request.headers.get("Api-Username"), "alice");
    return Response.json({ id: 4, topic_id: 2, post_number: 3, username: "admin" });
  });
  try {
    const result = body(await invoke("discourse_create_post", { topic_id: 2, raw: "body", author_username: "alice" }, ctx, opts));
    assert.equal(result.username, "admin");
    assert.equal(result.requested_author, "alice");
    assert.equal(result.author_applied, false);
  } finally { mock.restore(); }
});

test("user creation requires a global key and does not invent confirmation", async () => {
  const userKey = setup({ type: "user_api_key", key: "user-key" });
  const rejected = await invoke("discourse_create_user", { username: "sample", email: "sample@example.com", name: "Sample", password: "long-password" }, userKey.ctx, userKey.opts);
  assert.equal(rejected.isError, true);

  const apiKey = setup({ type: "api_key", key: "global", username: "admin" });
  const mock = mockFetch(() => Response.json({ success: true, active: false, message: "Check email" }));
  try {
    const result = body(await invoke("discourse_create_user", { username: "sample", email: "sample@example.com", name: "Sample", password: "long-password" }, apiKey.ctx, apiKey.opts));
    assert.equal(result.request_accepted, true);
    assert.equal(result.created, null);
    assert.equal(result.user_id, null);
    assert.equal(result.username, null);
    assert.equal(result.requested_username, "sample");
    assert.match(result.warning, /unconfirmed/);
  } finally { mock.restore(); }
});

test("topic creation preserves safe upstream validation details", async () => {
  const { ctx, opts } = setup({ type: "api_key", key: "global", username: "admin" });
  const mock = mockFetch(() => Response.json({ errors: ["Category is not allowed"], error_type: "invalid_access" }, { status: 422 }));
  try {
    const result = await invoke("discourse_create_topic", { title: "Topic", raw: "body", category_id: 1 }, ctx, opts);
    assert.equal(result.isError, true);
    assert.deepEqual(body(result).errors, ["Category is not allowed"]);
    assert.equal(body(result).status, 422);
  } finally { mock.restore(); }
});

test("administration tools expose discovery reads and confirmed activation routes", async () => {
  const { ctx, opts } = setup({ type: "api_key", key: "global", username: "admin" });
  const mock = mockFetch((request) => {
    if (request.url.endsWith("/categories/search.json")) return Response.json({ categories_count: 1, categories: [{ id: 4, name: "General", slug: "general", topic_count: 2 }] });
    if (request.url.includes("/admin/site_settings.json")) return Response.json({ site_settings: [{ setting: "title", value: "Forum", default: "Discourse", category: "required" }] });
    return new Response(null, { status: 204 });
  });
  try {
    const categories = body(await invoke("discourse_list_categories", {}, ctx, opts));
    assert.equal(categories.categories[0].id, 4);
    const settings = body(await invoke("discourse_list_site_settings", { names: ["title"] }, ctx, opts));
    assert.equal(settings.site_settings[0].setting, "title");
    const activation = body(await invoke("discourse_manage_user_activation", { username: "sample", action: "activate_and_approve", confirm: true }, ctx, opts));
    assert.deepEqual(activation.completed_actions, ["activate", "approve"]);
    assert.match(mock.requests.at(-2)!.url, /\/admin\/users\/sample\/activate\.json$/);
    assert.match(mock.requests.at(-1)!.url, /\/admin\/users\/sample\/approve\.json$/);
  } finally { mock.restore(); }
});

import test from "node:test";
import assert from "node:assert/strict";
import { Logger } from "../util/logger.js";
import { SiteState } from "../site/state.js";
import { filterTopicsTool, projectTopic } from "../tools/builtin/filter_topics.js";
import type { ToolContext, ToolRegistrationOptions } from "../tools/types.js";

function setup() {
  const logger = new Logger("silent");
  const siteState = new SiteState({ logger, timeoutMs: 5000, defaultAuth: { type: "none" } });
  siteState.selectSite("https://example.com");
  const ctx: ToolContext = { server: {} as any, siteState, logger, maxReadLength: 50000 };
  const opts: ToolRegistrationOptions = { allowWrites: false, toolsMode: "discourse_api_only" };
  return { ctx, opts };
}

async function invoke(input: Record<string, unknown>) {
  const { ctx, opts } = setup();
  return filterTopicsTool.handler(input as any, {} as any, ctx, opts);
}

function body(result: Awaited<ReturnType<typeof invoke>>): any {
  const content = result.content[0];
  return JSON.parse(content?.type === "text" ? content.text : "{}");
}

function mockFetch(payload: unknown) {
  const original = globalThis.fetch;
  const requests: Array<{ url: string; method: string }> = [];
  globalThis.fetch = async (input, init) => {
    requests.push({ url: String(input), method: init?.method ?? "GET" });
    return Response.json(payload);
  };
  return { requests, restore: () => { globalThis.fetch = original; } };
}

test("topic discovery preserves filtered calls and routes top and hot exactly", async () => {
  const mock = mockFetch({ topic_list: { topics: [] } });
  try {
    await invoke({ filter: "category:support status:open", page: 2, per_page: 15 });
    await invoke({ view: "top", top_period: "monthly", page: 1, per_page: 25 });
    await invoke({ view: "top" });
    const hot = body(await invoke({ view: "hot" }));

    assert.deepEqual(mock.requests.map((r) => r.url), [
      "https://example.com/filter.json?q=category%3Asupport+status%3Aopen&page=2&per_page=15",
      "https://example.com/top.json?period=monthly&page=1&per_page=25",
      "https://example.com/top.json?period=weekly&page=0&per_page=20",
      "https://example.com/top.json?period=daily&page=0&per_page=20",
    ]);
    assert.equal(hot.meta.view, "hot");
    assert.equal(hot.meta.top_period, "daily");
  } finally {
    mock.restore();
  }
});

test("invalid topic discovery combinations fail before HTTP", async () => {
  const mock = mockFetch({});
  try {
    for (const input of [
      {},
      { filter: "   " },
      { view: "top", filter: "tag:x" },
      { view: "hot", top_period: "daily" },
      { filter: "tag:x", top_period: "weekly" },
    ]) {
      const result = await invoke(input);
      assert.equal(result.isError, true);
    }
    assert.equal(mock.requests.length, 0);
  } finally {
    mock.restore();
  }
});

test("topic discovery returns a uniform rich sparse-safe projection and truthful pagination", async () => {
  const rich = {
    id: 123, slug: "topic-slug", title: "Topic title", category_id: 4, tags: ["support"],
    created_at: "2026-08-01T10:00:00Z", last_posted_at: "2026-08-17T12:00:00Z", bumped_at: "2026-08-17T12:00:00Z",
    posts_count: 38, reply_count: 37, views: 2100, like_count: 45, posters_count: 14,
    closed: false, archived: false, pinned: false, visible: true,
    posters: [{ user_id: 8, username: "alice", description: "Most Recent Poster", plugin_value: "ignored" }],
    solved: true,
  };
  const mock = mockFetch({ topic_list: { topics: [rich, { id: 2 }], more_topics_url: "/latest?before=2", total_count: 9 } });
  try {
    const output = body(await invoke({ filter: "status:open", per_page: 1 }));
    assert.deepEqual(output.results, [projectTopic(rich)]);
    assert.deepEqual(output.results[0].posters[0], { user_id: 8, username: "alice", description: "Most Recent Poster" });
    assert.equal(output.results[0].last_poster_username, "alice");
    assert.equal("solved" in output.results[0], false);
    assert.deepEqual(output.meta, {
      view: "filtered", top_period: null, page: 0, per_page: 1, returned: 1, has_more: true, total: 9,
    });
    const sparse = projectTopic({ id: 2 });
    assert.equal(sparse.slug, null);
    assert.equal(sparse.posts_count, null);
    assert.equal(sparse.posters, null);
  } finally {
    mock.restore();
  }
});

test("topic discovery never treats a full page as proof of continuation", async () => {
  const mock = mockFetch({ topic_list: { topics: [{ id: 1 }] } });
  try {
    const output = body(await invoke({ filter: "status:open", per_page: 1 }));
    assert.equal(output.meta.has_more, false);
    assert.equal("total" in output.meta, false);
  } finally {
    mock.restore();
  }
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { Logger } from '../util/logger.js';
import { HttpClient } from '../http/client.js';
import { SiteState } from '../site/state.js';
import { registerAllTools, type ToolRegistrationOptions } from '../tools/registry.js';
import type { ToolRegistrar } from '../tools/types.js';

interface ToolResult {
  isError?: boolean;
  content?: Array<{ type: string; text: string }>;
}

type ToolHandler = (args: Record<string, unknown>, extra: unknown) => Promise<ToolResult>;

function createMockServer(): { server: ToolRegistrar; tools: Record<string, { handler: ToolHandler }> } {
  const tools: Record<string, { handler: ToolHandler }> = {};
  const server = {
    registerTool(name: string, _meta: Record<string, unknown>, handler: ToolHandler) {
      tools[name] = { handler };
    },
  } as ToolRegistrar;
  return { server, tools };
}

function mockJsonFetch(calls: string[]) {
  const originalFetch = globalThis.fetch;
  globalThis.fetch = (async (input: RequestInfo | URL, _init?: RequestInit) => {
    const url = typeof input === 'string' ? input : input.toString();
    calls.push(url);
    if (url.endsWith('/about.json')) {
      return new Response(JSON.stringify({ about: { title: 'Example Discourse' } }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    if (url.includes('/search.json')) {
      return new Response(JSON.stringify({ topics: [{ id: 123, title: 'Hello World', slug: 'hello-world' }] }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    if (url.endsWith('/site.json')) {
      return new Response(JSON.stringify({ site: { title: 'Example Discourse' } }), { status: 200, headers: { 'Content-Type': 'application/json' } });
    }
    return new Response('not found', { status: 404 });
  }) as typeof fetch;
  return () => {
    globalThis.fetch = originalFetch;
  };
}

test('SiteState preserves and normalizes subfolder base paths', () => {
  const logger = new Logger('silent');
  const siteState = new SiteState({ logger, timeoutMs: 5000, defaultAuth: { type: 'none' } });

  const first = siteState.buildClientForSite('https://example.com/forum');
  const second = siteState.buildClientForSite('https://example.com/forum/');

  assert.equal(first.base, 'https://example.com/forum');
  assert.equal(second.base, 'https://example.com/forum');
  assert.equal(first.client, second.client);
});

test('HttpClient routes leading-slash paths under subfolder base', async () => {
  const calls: string[] = [];
  const restoreFetch = mockJsonFetch(calls);
  const logger = new Logger('silent');
  const client = new HttpClient({ baseUrl: 'https://example.com/forum', timeoutMs: 5000, logger, auth: { type: 'none' } });

  try {
    await client.get('/about.json');
    assert.equal(calls[0], 'https://example.com/forum/about.json');
  } finally {
    restoreFetch();
  }
});

